class User private constructor(val name: String) {
    companion object {
        const val MAX_NAME_LENGTH = 50

        fun fromInput(raw: String): User {
            val trimmed = raw.trim().take(MAX_NAME_LENGTH)
            return User(trimmed)
        }
    }
}

val u = User.fromInput("  براء  ")   // عبر اسم الصنف مباشرة
println(User.MAX_NAME_LENGTH)          // 50

