fun parseAge(input: String): Int {
    return try {
        input.trim().toInt()
    } catch (e: NumberFormatException) {
        println("إدخال غير صالح: $input")
        -1
    } finally {
        println("انتهت محاولة التحويل")
    }
}

class InvalidAgeException(msg: String) : Exception(msg)

fun validate(age: Int) {
    require(age in 0..120) { "عمر غير منطقي: $age" }
}

