import kotlinx.coroutines.*

suspend fun fetchUser(id: Int): String {
    delay(500)              // انتظار غير محظور للخيط
    return "مستخدم #$id"
}

fun main() = runBlocking {
    launch { println(fetchUser(1)) }   // خلفية، بلا انتظار نتيجة هنا

    val a = async { fetchUser(2) }
    val b = async { fetchUser(3) }
    println("${a.await()} و ${b.await()}")  // ينفّذان بالتوازي
}

